using System.ComponentModel;
using System.Net;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

const string modelId = "gpt-4o-mini-2024-07-18";

IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

var notebook = new Notebook();

List<AITool> tools =
[
    AIFunctionFactory.Create(WebSearchTool.SearchAsync),
    AIFunctionFactory.Create(WebSearchTool.FetchPageAsync),
    AIFunctionFactory.Create(notebook.AddNote),
    AIFunctionFactory.Create(notebook.GetNotes),
];

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. When given a topic you must:
        1. Search the web for information using the search tool.
        2. Fetch the most relevant pages to get detailed content.
        3. Take notes on key findings using the note-taking tool.
        4. After researching, retrieve your notes and produce a concise summary
           with the most important facts, organized under clear headings.
        Always cite your sources.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and summarizing findings.",
    tools: tools);

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       Research Agent (powered by AI) ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine();

if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine();
Console.WriteLine($"Researching: {topic}");
Console.WriteLine(new string('─', 50));

var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 4096,
});

var response = await agent.RunAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    session: null,
    options: runOptions);

Console.WriteLine();
Console.WriteLine("═══════════════ RESEARCH SUMMARY ═══════════════");
Console.WriteLine(response.OutputText);
Console.WriteLine("════════════════════════════════════════════════");

// ---------- Tool implementations ----------

/// <summary>Provides web search capabilities using a search API.</summary>
static class WebSearchTool
{
    private static readonly HttpClient s_http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
            { "Accept", "text/html" },
        },
        Timeout = TimeSpan.FromSeconds(15),
    };

    [Description("Searches the web for the given query and returns a list of result snippets with URLs. Use this to discover relevant pages.")]
    public static async Task<string> SearchAsync(
        [Description("The search query")] string query,
        CancellationToken cancellationToken = default)
    {
        Console.WriteLine($"  🔍 Searching: \"{query}\"");

        try
        {
            // Use DuckDuckGo HTML search (no API key required)
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";
            var html = await s_http.GetStringAsync(url, cancellationToken);

            var results = ParseDuckDuckGoResults(html);
            if (results.Count == 0)
            {
                return "No search results found.";
            }

            return string.Join("\n\n", results.Take(5));
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    [Description("Fetches the text content of a web page at the given URL. Use this to read detailed content from a search result.")]
    public static async Task<string> FetchPageAsync(
        [Description("The full URL to fetch")] string url,
        CancellationToken cancellationToken = default)
    {
        Console.WriteLine($"  📄 Fetching: {url}");

        try
        {
            var html = await s_http.GetStringAsync(url, cancellationToken);

            // Strip HTML tags for a rough plain-text extraction
            var text = System.Text.RegularExpressions.Regex.Replace(html, "<[^>]+>", " ");
            text = System.Text.RegularExpressions.Regex.Replace(text, @"\s+", " ");
            text = WebUtility.HtmlDecode(text).Trim();

            // Limit to ~4000 chars to stay within context budget
            if (text.Length > 4000)
            {
                text = text[..4000] + "… [truncated]";
            }

            return text;
        }
        catch (Exception ex)
        {
            return $"Failed to fetch page: {ex.Message}";
        }
    }

    private static List<string> ParseDuckDuckGoResults(string html)
    {
        var results = new List<string>();
        // DuckDuckGo HTML results are in <a class="result__a"> with snippets in <a class="result__snippet">
        var linkPattern = new System.Text.RegularExpressions.Regex(
            @"<a[^>]+class=""result__a""[^>]*href=""([^""]+)""[^>]*>(.*?)</a>",
            System.Text.RegularExpressions.RegexOptions.Singleline);
        var snippetPattern = new System.Text.RegularExpressions.Regex(
            @"<a[^>]+class=""result__snippet""[^>]*>(.*?)</a>",
            System.Text.RegularExpressions.RegexOptions.Singleline);

        var links = linkPattern.Matches(html);
        var snippets = snippetPattern.Matches(html);

        for (int i = 0; i < Math.Min(links.Count, 8); i++)
        {
            var rawUrl = WebUtility.HtmlDecode(links[i].Groups[1].Value);
            // DuckDuckGo wraps URLs in a redirect; extract the real URL
            var uddgMatch = System.Text.RegularExpressions.Regex.Match(rawUrl, @"uddg=([^&]+)");
            var finalUrl = uddgMatch.Success
                ? WebUtility.UrlDecode(uddgMatch.Groups[1].Value)
                : rawUrl;

            var title = System.Text.RegularExpressions.Regex.Replace(
                links[i].Groups[2].Value, "<[^>]+>", "").Trim();

            var snippet = i < snippets.Count
                ? System.Text.RegularExpressions.Regex.Replace(
                    snippets[i].Groups[1].Value, "<[^>]+>", "").Trim()
                : "";

            results.Add($"Title: {title}\nURL: {finalUrl}\nSnippet: {snippet}");
        }

        return results;
    }
}

/// <summary>A simple in-memory notebook for the agent to store and retrieve research notes.</summary>
sealed class Notebook
{
    private readonly List<string> _notes = [];

    [Description("Saves a research note. Use this to record key findings, facts, or quotes during research.")]
    public string AddNote(
        [Description("The note text to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📝 Note saved ({_notes.Count} total)");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieves all saved research notes. Use this before writing your final summary.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes saved yet.";
        }

        Console.WriteLine($"  📋 Retrieving {_notes.Count} note(s)");
        return string.Join("\n---\n",
